#!/usr/bin/env bash
# PreToolUse(Edit|Write): block edits to env files, lockfiles and generated data.
f=$(node -e 'let d="";process.stdin.on("data",c=>d+=c).on("end",()=>{try{process.stdout.write(JSON.parse(d).tool_input?.file_path??"")}catch{}})')
case "$f" in
  */.env*|.env*) echo "Blocked: .env files are off limits." >&2; exit 2 ;;
  *pnpm-lock.yaml|*package-lock.json|*yarn.lock) echo "Blocked: change the lockfile only through pnpm." >&2; exit 2 ;;
  */public/data/*|public/data/*) echo "Blocked: public/data is generated by pnpm ingest." >&2; exit 2 ;;
esac
exit 0
